  wV = `지금 추천하세요. 투표는 12월에 진행됩니다.`,
  TV = `본 이벤트의 Steam 어워드는 막을 내렸습니다. 올해 가을 및 겨울 할인 기간에 진행될 연간 Steam 어워드를 확인하세요!`,
