  kV = `%1$s 게임을 Steam 어워드 페이지의 수상 부문에 추천하려면 여기를 클릭하세요.`,
  AV = `후보작 추천이 종료되었습니다. 겨울 할인 기간 동안 투표하세요. 수상작은 1월 2일에 발표됩니다.`,
  jV = `투표가 종료되었습니다. 결과를 확인하려면 여기를 클릭하세요.`,
  MV = `추천 부문:`,
  NV = `내 추천작 보기`,
