  Mpe = `Steam Deck 프레임 속도 데이터는 프레임 속도 데이터를 제공하는 데 동의한 Steam Deck 사용자가 지난 %1$s일 동안 제출한 프레임 속도 보고서를 기반으로 합니다.`,
  Npe = `Steam Deck 프레임 속도 데이터는 프레임 속도 데이터를 제공하는 데 동의한 Steam Deck 사용자의 프레임 속도 보고서를 기반으로 합니다.`,
  Ppe = `참고: 현재는 변동성 데이터가 제공되지 않지만 베타 기간에 제공될 예정입니다. 변동성 데이터를 통해 프레임 속도가 안정적인지 아니면 크게 변동하는지 확인할 수 있습니다.`,
  Fpe = `이유`,
  Ipe = `응답 수`,
  Lpe = `히스토그램 데이터는 프레임 속도 데이터를 제공하는 데 동의한 사용자가 %2$s에서 제출한 %1$s의 프레임 속도 보고서를 기반으로 합니다.`,
  Rpe = `히스토그램 데이터는 프레임 속도 데이터를 제공하는 데 동의한 사용자가 %1$s에서 제출한 해당 게임의 프레임 속도 보고서를 기반으로 합니다.`,
  zpe = `프레임 속도 분포`,
  Bpe = `프레임 속도`,
  Vpe = `샘플 비율(%)`,
  Hpe = `충분한 데이터가 수집되면 차트가 표시됩니다.`,
  Upe = `모든 데이터 포함`,
  Wpe = `기본적으로 기기의 프레임 속도 제한이 기본값으로 설정되어 있지 않으면 해당 데이터는 제외됩니다.`,
  Gpe = `Steam Deck LCD`,
  Kpe = `Steam Deck OLED`,
  qpe = `Steam Deck 모델`,
  Jpe = `프레임 속도 분포`,
  Ype = `Steam은 %2$s에서 %1$s에 대한 프레임 속도 데이터를 계속 수집하고 있습니다.`,
  Xpe = `Steam은 %1$s에서 해당 게임에 대한 프레임 속도 데이터를 계속 수집하고 있습니다.`,
  Zpe = `Steam은 해당 게임에 대한 프레임 속도 데이터를 계속 수집하고 있습니다.`,
  Qpe = `이 차트는 %2$s에서 %1$s 플레이 시 익명화된 데이터 수집에 동의한 플레이어의 프레임 속도 샘플을 보여줍니다. 각 막대는 해당 프레임 속도에서 수집된 샘플의 비율을 나타냅니다.`,
  $pe = `이 차트는 %1$s 플레이 시 익명화된 데이터 수집에 동의한 플레이어의 프레임 속도 샘플을 보여줍니다. 각 막대는 해당 프레임 속도에서 수집된 샘플의 비율을 나타냅니다.`,
  eme = `세부 정보`,
  tme = `%1$s의 기본 프레임 속도 제한인 %2$sFPS에서 수집된 데이터만 포함됩니다. 대기 시간이나 유효하지 않은 샘플은 필터링되어 제외되며, 각 게임플레이 세션에서 여러 개의 샘플을 수집합니다.`,
  nme = `차트에 표시되는 간격(예: %1$sFPS와 %2$sFPS 사이)은 VSync로 인해 발생할 수 있습니다. VSync는 화면 찢김 현상을 방지하기 위해 게임의 프레임 속도를 디스플레이의 새로 고침 빈도에 맞춰 동기화합니다. 이에 따라 게임의 평균 프레임 속도가 %1$sFPS와 %2$sFPS 사이인 경우에도 샘플이 해당 구간에 집중될 수 있습니다. 이는 VSync의 정상적인 동작이며, 프레임 페이싱에 영향을 미칠 수는 있지만 눈에 띄게 끊김 현상을 유발하지는 않습니다.`,
  rme = `베타`,
  ime = `%1$s 창작마당 콘텐츠`,
  ame = `%1$s 스크린샷`,
  ome = `%1$s 동영상`,
  sme = `커뮤니티가 만든 %1$s 아트워크`,
  cme = `Greenlight 게임`,
  lme = `Greenlight 콘셉트`,
  ume = `Greenlight 소프트웨어`,
